{
  "cypher": "MATCH (ge:Company {name: \"General Electric\"})-[:hasBoardMember]->(p:Person)\nMATCH (c:Company)-[:foundedBy]->(p)\nRETURN DISTINCT c.name AS companyName, c.launch_year AS launchYear"

  ,
  "rationale": "The query first finds the General Electric company node, then all persons who served on its board via the `hasBoardMember` relationship. It then finds every company that was founded by any of those persons using the `foundedBy` relationship. Finally, it returns each company’s name and launch year, ensuring no duplicates with `DISTINCT`."
}

{
  "cypher": "MATCH (c:Company)\nWHERE ( (c)-[:foundedBy]->(:Person {name: 'Sergey Brin'}) )\n   OR ( (j:Company {name: 'Jambool'})-[:subsidiaryOf]->(c) )\nRETURN count(DISTINCT c) AS companyCount"
  ,
  "rationale": "Counts distinct companies that were founded by Sergey Brin or that have Jambool as a subsidiary, using the provided schema."
}

{
  "cypher": "MATCH (c:Company)-[:hasCEO]->(p:Person)\nWHERE p.name = \"Marianne Laigneau\"\nRETURN c.name AS companyName, c.launch_year AS launchYear"

  , "rationale": "Matches companies that have had Marianne Laigneau as CEO and returns each company's name and launch year, using only the provided schema."
}

