{
  "cypher": "MATCH (c:Company)-[:subsidiaryOf]->(s:Company)-[:hasCEO]->(p:Person)\nWHERE p.name = \"Mario Rossetti\" OR \"Mario Rossetti\" IN p.aliases\nRETURN min(toInteger(c.launch_year)) AS earliest_launch_year"
  ,
  "rationale": "The query finds companies that own a subsidiary (via `subsidiaryOf`) which had Mario Rossetti as CEO (via `hasCEO`). It then returns the smallest `launch_year` among those companies, converting the string year to an integer for correct ordering."
}

{
  "cypher": "MATCH (p:Person)-[:hasCEO]->(c:Company)-[:basedIn]->(co:Country {name: \"Italy\"})\nRETURN p.name AS CEO, count(c) AS companyCount\nORDER BY companyCount DESC"

  , "rationale": "Matches CEOs (Person) who have led companies (Company) based in Italy (Country with name \"Italy\"). Counts distinct companies per CEO and orders by the count."
}

{
